import {mapState} from 'vuex';
import {productSpecsList} from '@/api/product';

export default {
  name: "specs",
  data() {
    return {
      grid: {
        xl: 7,
        lg: 7,
        md: 12,
        sm: 24,
        xs: 24
      },
      loading: false,
      columns1: [
        {
          title: 'ID',
          key: 'id',
          width: 80
        },
        {
          title: '参数模板名称',
          key: 'name',
          minWidth: 100
        },
        {
          title: '排序',
          key: 'sort',
          width: 100
        },
        {
          title: '创建时间',
          key: 'add_time',
          minWidth: 100
        },
        {
          title: '操作',
          slot: 'action',
          fixed: 'right',
          minWidth: 120
        }
      ],
      specsFrom: {
        page: 1,
        limit: 15,
        name: ''
      },
      list: [],
      total: 0
    }
  },
  computed: {
    ...mapState('admin/layout', [
      'isMobile'
    ]),
    labelWidth() {
      return this.isMobile ? undefined : 96;
    },
    labelPosition() {
      return this.isMobile ? 'top' : 'right';
    }
  },
  created() {
    this.getList();
  },
  methods: {
    specsSearchs() {
      this.specsFrom.page = 1;
      this.list = [];
      this.getList();
    },
    // 添加
    add() {
      this.$router.push({path: "/admin/product/ensure/create/" + 0});
    },
    // 单位列表
    getList() {
      this.loading = true;
      productSpecsList(this.specsFrom).then(res => {
        let data = res.data;
        this.list = data.list;
        this.total = data.count;
        this.loading = false;
      }).catch(err => {
        this.loading = false;
        this.$Message.error(err.msg);
      })
    },
    pageChange(index) {
      this.specsFrom.page = index;
      this.getList();
    },
    //修改
    edit(id) {
      this.$router.push({path: "/admin/product/ensure/create/" + id});
    },
    // 删除
    del(row, tit, num) {
      let delfromData = {
        title: tit,
        num: num,
        url: `product/specs/${row.id}`,
        method: 'DELETE',
        ids: ''
      };
      this.$modalSure(delfromData).then((res) => {
        this.$Message.success(res.msg);
        this.list.splice(num, 1);
        if (!this.list.length) {
          this.specsFrom.page =
              this.specsFrom.page == 1 ? 1 : this.specsFrom.page - 1;
        }
        this.getList();
      }).catch(err => {
        this.$Message.error(err.msg);
      });
    }
  }
}
